inline const GraphKernelRegisterPolicy& policy(const char* profile) {
  if (std::strcmp(profile, "gr00t_z2_register_policy") == 0) return gr00t_z2_register_policy();
  if (std::strcmp(profile, "lingbot2_multiview_w8_register_policy") == 0) return lingbot2_multiview_w8_register_policy();
  if (std::strcmp(profile, "qwen3vl_pooler_z1_register_policy") == 0) return qwen3vl_pooler_z1_register_policy();
  if (std::strcmp(profile, "qwen3vl_pooler_ds1_register_policy") == 0) return qwen3vl_pooler_ds1_register_policy();
  if (std::strcmp(profile, "qwen3vl_pooler_ds3_register_policy") == 0) return qwen3vl_pooler_ds3_register_policy();
  if (std::strcmp(profile, "qwen3vl_pooler_ds3_partial_mrope_register_policy") == 0) return qwen3vl_pooler_ds3_partial_mrope_register_policy();
  if (std::strcmp(profile, "groot_n17_pooler_ds3_register_policy") == 0) return groot_n17_pooler_ds3_register_policy();
  TORCH_CHECK(false, "unknown frozen parallel_linear census profile: ", profile);
}
